// Practice question bank in the three official DSR MCQ formats.
// type: 's' stand-alone, 'c' case-based (case = key in CASES), 'e' extended matching (emq = key in EMQS).
// ans is the index of the correct option. Stand-alone and case options are shuffled at runtime.
const CASES = {
  t2dm: {t: 4, text: "Mark, 52, truck driver, newly diagnosed type 2 diabetes, BMI 33, HbA1c 8.4% (68 mmol/mol). Diet history: 4 Weet-Bix with full-cream milk and 2 tsp sugar; 2 meat pies from a service station at lunch; 1.25 L regular cola across the day; dinner of steak, chips and a small salad; 3-4 beers most nights."},
  aged: {t: 13, text: "Joan, 86, lives in residential aged care. She has lost 6 kg (10%) over 3 months, eats about half of each meal, has new dentures that hurt, and is on a 'diabetic diet' for diet-controlled type 2 diabetes (HbA1c 6.1%). MNA-SF score 6."},
  refeed: {t: 8, text: "A 34-year-old man is admitted after 2 weeks of minimal food intake during an alcohol binge. BMI 17.5. Bloods on admission: potassium 3.2 mmol/L, phosphate 0.65 mmol/L, magnesium 0.6 mmol/L. The team wants to start nasogastric feeding."},
  preg: {t: 10, text: "Ana, 29, is 10 weeks pregnant with her first baby. She is vegetarian (eats dairy and eggs), works long hours, often has a ham-free brie and salad baguette from a café for lunch and takes no supplements. Pre-pregnancy BMI 23."},
  infant: {t: 9, text: "Leo is 7 months old, exclusively breastfed, and his parents have not started solids because his older sister has eczema and a peanut allergy. His weight has moved from the 50th to the 25th centile over 2 months."},
  ckd: {t: 7, text: "Mrs Nguyen, 68, has CKD stage 4 (eGFR 22), type 2 diabetes and hypertension. She speaks limited English and her son usually translates. Bloods: potassium 5.9 mmol/L, phosphate 1.7 mmol/L. She eats rice with most meals and a lot of fruit."},
  menu: {t: 14, text: "You are the new dietitian at a 120-bed residential aged care home. The cook-fresh kitchen uses a 2-week menu cycle. Residents complain the food is repetitive and the evening meal is soup and sandwiches. Several residents need IDDSI level 4 and 5 meals."},
  coeliac: {t: 6, text: "Priya, 24, has bloating, fatigue and iron deficiency anaemia. She read online about gluten and stopped eating bread and pasta 3 weeks ago, and feels a little better. Her GP has ordered coeliac serology."}
};
const EMQS = {
  nutrients: {t: 11, lead: "For each client choose the nutrient of MOST concern. An option may be used more than once.", opts: ["Calcium", "Iron", "Zinc", "Vitamin B12", "Folate", "Vitamin D", "Iodine", "Vitamin K", "Thiamine"]},
  tools: {t: 3, lead: "For each situation choose the MOST appropriate tool or method. An option may be used more than once.", opts: ["Malnutrition Screening Tool", "Subjective Global Assessment", "MNA short form", "24-hour recall", "Food frequency questionnaire", "Weighed food record", "WHO growth chart", "CDC growth chart", "IDDSI flow test"]},
  designs: {t: 17, lead: "For each research question choose the MOST appropriate study design.", opts: ["Randomised controlled trial", "Prospective cohort study", "Case-control study", "Cross-sectional survey", "Systematic review and meta-analysis", "Qualitative interviews", "Case report", "Crossover trial"]},
  funding: {t: 18, lead: "For each client choose the MOST likely funding pathway for dietitian care.", opts: ["Medicare GP Chronic Condition Management Plan", "NDIS plan", "Department of Veterans' Affairs", "Eating Disorder Treatment Plan", "Private health insurance extras", "Public hospital outpatient clinic", "Aged care provider", "Workers compensation"]},
  diets: {t: 7, lead: "For each condition choose the MOST appropriate first dietary focus.", opts: ["Strict lifelong gluten-free diet", "Low FODMAP diet trial with reintroduction", "Late evening carbohydrate snack", "Potassium restriction", "Texture-modified diet as prescribed by speech pathology", "High energy high protein food fortification", "Exclusive enteral nutrition", "Low saturated fat dietary pattern", "Low iodine diet"]}
};
const QUESTIONS = [
// 1 Core science
{t:1,type:'s',stem:"A patient has had 100 cm of terminal ileum removed. Which nutrient is MOST likely to become deficient long term?",opts:["Vitamin B12","Vitamin C","Folate","Iron"],ans:0,why:"B12–intrinsic factor complexes and bile salts are absorbed in the terminal ileum. Iron is absorbed mostly in the duodenum.",src:"https://pressbooks.oer.hawaii.edu/humannutrition2e22/chapter/2-the-digestive-system/"},
{t:1,type:'s',stem:"After 3 days of fasting, the brain gets an increasing share of its energy from",opts:["ketone bodies","dietary glucose","fatty acids directly","muscle glycogen"],ans:0,why:"Fatty acids cannot cross the blood-brain barrier well. In prolonged fasting the liver makes ketones from fat and the brain adapts to use them.",src:"https://openstax.org/books/anatomy-and-physiology-2e/pages/24-5-metabolic-states-of-the-body"},
{t:1,type:'s',stem:"Which hormone MOST directly promotes glycogen storage after a meal?",opts:["Insulin","Glucagon","Cortisol","Adrenaline"],ans:0,why:"Insulin rises in the fed state and promotes glycogenesis and fat storage. The others raise blood glucose.",src:"https://openstax.org/books/anatomy-and-physiology-2e/pages/24-2-carbohydrate-metabolism"},
{t:1,type:'s',stem:"The liver disposes of nitrogen from amino acid breakdown mainly by producing",opts:["urea","creatinine","uric acid","ketones"],ans:0,why:"Deamination produces ammonia, converted to urea in the liver (urea cycle) and excreted by the kidneys.",src:"https://openstax.org/books/anatomy-and-physiology-2e/pages/24-4-protein-metabolism"},
{t:1,type:'s',stem:"A food label shows 1250 kJ per serve. This is closest to",opts:["300 kcal","125 kcal","520 kcal","5200 kcal"],ans:0,why:"1 kcal = 4.184 kJ, so 1250 ÷ 4.184 ≈ 299 kcal.",src:"https://www.eatforhealth.gov.au/food-essentials/how-much-do-we-need-each-day/serve-sizes"},
// 2 ADG & NRV
{t:2,type:'s',stem:"Which is ONE standard serve of grain (cereal) foods?",opts:["½ cup cooked rice","1 cup cooked rice","2 slices of bread","1 cup of muesli"],ans:0,why:"One grain serve = 1 slice bread (40 g), ½ cup cooked rice, pasta or porridge, ¼ cup muesli.",src:"https://www.eatforhealth.gov.au/food-essentials/how-much-do-we-need-each-day/serve-sizes"},
{t:2,type:'s',stem:"Which is ONE standard serve from the lean meat and alternatives group?",opts:["2 large eggs","1 large egg","40 g cheese","200 g yoghurt"],ans:0,why:"2 large eggs (120 g) is one serve. Cheese and yoghurt are in the dairy group.",src:"https://www.eatforhealth.gov.au/food-essentials/how-much-do-we-need-each-day/serve-sizes"},
{t:2,type:'s',stem:"How many serves of vegetables are recommended daily for a woman aged 30?",opts:["5","3","6","7½"],ans:0,why:"Women 19-50: 5 serves of vegetables and legumes; men 19-50: 6.",src:"https://www.eatforhealth.gov.au/food-essentials/how-much-do-we-need-each-day/recommended-number-serves-adults"},
{t:2,type:'s',stem:"To plan the diet of an individual client, which nutrient reference value should you aim for?",opts:["Recommended Dietary Intake","Estimated Average Requirement","Upper Level of Intake","Suggested Dietary Target"],ans:0,why:"The RDI covers 97-98% of healthy people, so it is the target for individuals. EAR is for assessing groups.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/introduction"},
{t:2,type:'s',stem:"According to NHMRC guidance, a healthy adult should drink no more than",opts:["10 standard drinks a week","14 standard drinks a week","2 standard drinks every day","21 standard drinks a week"],ans:0,why:"No more than 10 standard drinks a week and no more than 4 on any one day.",src:"https://www.nhmrc.gov.au/health-advice/alcohol"},
{t:2,type:'s',stem:"Which counts as ONE serve of dairy and alternatives?",opts:["250 mL calcium-fortified soy milk","250 mL unfortified almond milk","1 cup of cream","2 tablespoons cream cheese"],ans:0,why:"Plant milks count only when fortified with at least 100 mg calcium per 100 mL. Cream and cream cheese are discretionary.",src:"https://www.eatforhealth.gov.au/food-essentials/how-much-do-we-need-each-day/serve-sizes"},
{t:2,type:'s',stem:"The acceptable macronutrient distribution range for fat in adults is",opts:["20-35% of energy","10-20% of energy","35-45% of energy","45-65% of energy"],ans:0,why:"AMDR: protein 15-25%, fat 20-35%, carbohydrate 45-65%.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/introduction"},
// 3 Assessment / NCP
{t:3,type:'s',stem:"Which is a correctly structured PES statement?",opts:["Excessive energy intake related to frequent takeaway meals as evidenced by weight gain of 8 kg in 6 months","Obesity related to diabetes as evidenced by BMI 34","Weight gain related to poor diet as evidenced by eating too much","Type 2 diabetes related to excess weight as evidenced by HbA1c of 8%"],ans:0,why:"P must be a nutrition problem the dietitian can treat (not a medical diagnosis), E a cause, S measurable evidence.",src:"https://www.eatrightpro.org/practice/nutrition-care-process/ncp-overview/nutrition-diagnosis"},
{t:3,type:'s',stem:"You need to estimate the usual intake of one outpatient in a 45-minute first consultation. The MOST suitable method is a",opts:["diet history interview","food frequency questionnaire","single 24-hour recall","7-day weighed food record"],ans:0,why:"A diet history estimates usual intake for an individual in a clinic. One 24-hour recall does not show usual intake; weighed records are burdensome and slow.",src:"https://www.measurement-toolkit.org/diet/diet-decision-matrix"},
{t:3,type:'s',stem:"Which step of the Nutrition Care Process comes immediately after assessment?",opts:["Nutrition diagnosis","Nutrition intervention","Monitoring and evaluation","Nutrition screening"],ans:0,why:"Assessment → diagnosis → intervention → monitoring and evaluation. Screening happens before the NCP to decide who needs it.",src:"https://www.eatrightpro.org/practice/nutrition-care-process/ncp-overview"},
{t:3,type:'s',stem:"A 70 kg adult inpatient without kidney disease is unwell but not critically ill. A reasonable entry-level protein estimate is",opts:["70-105 g a day","35-50 g a day","140-175 g a day","20-30 g a day"],ans:0,why:"About 1.0-1.5 g/kg/day for many unwell adults (check local protocol, e.g. Queensland Health NEMO).",src:"https://www.health.qld.gov.au/__data/assets/pdf_file/0022/144175/est-req.pdf"},
{t:3,type:'e',emq:'tools',stem:"Screening every adult on admission to an acute hospital ward",ans:0,why:"The MST is a quick validated screen used on admission in many Australian hospitals.",src:"https://www.health.qld.gov.au/nutrition/patients/subjective-global-assessment-training-videos"},
{t:3,type:'e',emq:'tools',stem:"Full assessment of malnutrition severity in an adult surgical inpatient",ans:1,why:"SGA rates A/B/C from history and physical exam.",src:"https://www.health.qld.gov.au/nutrition/patients/subjective-global-assessment-training-videos"},
{t:3,type:'e',emq:'tools',stem:"Screening a resident in a residential aged care home",ans:2,why:"MNA-SF is validated for older people and recommended by the Aged Care Commission.",src:"https://www.agedcarequality.gov.au/quality-standards/guide-completing-mini-nutritional-assessment-short-form"},
{t:3,type:'e',emq:'tools',stem:"Plotting the weight of an 18-month-old",ans:6,why:"Australia uses WHO charts from 0-2 years and CDC charts from 2-18 years.",src:"https://www.rch.org.au/childgrowth/about_child_growth/Growth_charts/"},
{t:3,type:'e',emq:'tools',stem:"Ranking habitual calcium intake in 5000 adults for a population study",ans:4,why:"FFQs rank habitual intake in large groups cheaply.",src:"https://www.measurement-toolkit.org/diet/diet-decision-matrix"},
{t:3,type:'e',emq:'tools',stem:"Checking a mildly thick drink is the right consistency",ans:8,why:"The IDDSI flow test (10 mL syringe, 10 seconds) classifies drinks levels 0-4.",src:"https://www.iddsi.org/standards/framework"},
// 4 Diabetes
{t:4,type:'c',case:'t2dm',stem:"Other than reducing energy, which change will MOST improve Mark's blood glucose levels?",opts:["Replace regular cola with water or diet drinks","Swap Weet-Bix for rolled oats","Remove the salad from dinner","Change full-cream milk to skim"],ans:0,why:"1.25 L of cola is about 130 g of sugar a day. It is his largest single source of rapidly absorbed carbohydrate.",src:"https://baker.edu.au/health-hub/fact-sheets/carbohydrates-gi"},
{t:4,type:'c',case:'t2dm',stem:"Which food group is Mark MOST clearly not meeting minimum serves for?",opts:["Vegetables","Grain foods","Meat and alternatives","Dairy foods"],ans:0,why:"A small salad is about 1 serve of vegetables against 6 recommended for men. He has plenty of grains (Weet-Bix, pastry) and meat.",src:"https://www.eatforhealth.gov.au/food-essentials/how-much-do-we-need-each-day/recommended-number-serves-adults"},
{t:4,type:'c',case:'t2dm',stem:"Mark says he cannot cook at work because he is on the road. The MOST helpful lunch strategy is",opts:["Plan service-station swaps and pack simple food","Skip lunch and eat more at dinner","Replace lunch with a meal-replacement shake","Tell him to bring a cooked hot meal"],ans:0,why:"Practical, person-centred change he can do on the road. Skipping meals can worsen glycaemic control and hunger.",src:"https://www.diabetesaustralia.com.au/living-with-diabetes/healthy-eating/"},
{t:4,type:'c',case:'t2dm',stem:"After the first education session, follow-up with Mark would usually be",opts:["about one month later","the next day","in 12 months","only if HbA1c rises"],ans:0,why:"Typical outpatient review is around a month after initial education, to review changes and set next goals.",src:"https://dietitiansaustralia.org.au/media/394"},
{t:4,type:'s',stem:"A client on insulin has a blood glucose of 3.4 mmol/L and is alert. The FIRST step is to give",opts:["150 mL of regular soft drink","a ham sandwich","a glass of milk","a handful of nuts"],ans:0,why:"Treat first with 15 g of fast-acting carbohydrate (e.g. 150 mL regular soft drink, 3 glucose tablets, or 3-5 jelly beans depending on brand), recheck in 10-15 minutes, then have a longer-acting carbohydrate or the next meal.",src:"https://baker.edu.au/health-hub/fact-sheets/hypoglycaemia-management"},
{t:4,type:'s',stem:"Which result on a 75 g OGTT at 26 weeks is diagnostic of gestational diabetes?",opts:["Fasting 5.3 mmol/L","1 hour 9.4 mmol/L","2 hours 7.9 mmol/L","Fasting 4.6 mmol/L"],ans:0,why:"Any one of fasting ≥ 5.1, 1 h ≥ 10.0, 2 h ≥ 8.5 mmol/L.",src:"https://www.baker.edu.au/health-hub/fact-sheets/gestational-diabetes"},
{t:4,type:'s',stem:"A food has a glycaemic index of 52. It is classified as",opts:["low GI","medium GI","high GI","GI not applicable"],ans:0,why:"Low ≤ 55, medium 56-69, high ≥ 70.",src:"https://baker.edu.au/health-hub/fact-sheets/carbohydrates-gi"},
{t:4,type:'s',stem:"A Brazilian lab report shows fasting glucose 144 mg/dL. In Australian units this is about",opts:["8.0 mmol/L","14.4 mmol/L","4.0 mmol/L","2.6 mmol/L"],ans:0,why:"Divide mg/dL by 18: 144 ÷ 18 = 8.0 mmol/L.",src:"https://www.diabetesaustralia.com.au/living-with-diabetes/healthy-eating/"},
// 5 CVD & weight
{t:5,type:'s',stem:"For lowering LDL cholesterol, butter on toast is BEST replaced with",opts:["avocado or a margarine spread","coconut oil","ghee","no spread and extra jam"],ans:0,why:"Replace saturated fat with unsaturated fat. Coconut oil and ghee are high in saturated fat; swapping to refined carbohydrate gives little benefit.",src:"https://www.heartfoundation.org.au/healthy-living/healthy-eating/fats-oils-and-heart-health"},
{t:5,type:'s',stem:"Which food is usually the LARGEST source of sodium in the Australian diet?",opts:["Bread and bread rolls","Fresh fruit","Plain milk","Fresh chicken"],ans:0,why:"Bread is a leading contributor because it is eaten often; processed meats, sauces and takeaway also contribute a lot.",src:"https://www.heartfoundation.org.au/healthy-living/healthy-eating/salt-and-heart-health"},
{t:5,type:'s',stem:"A food contains 400 mg sodium per serve. This is equal to about",opts:["1 g salt","0.4 g salt","4 g salt","0.16 g salt"],ans:0,why:"Salt = sodium × 2.5. 400 mg × 2.5 = 1000 mg = 1 g salt.",src:"https://www.heartfoundation.org.au/healthy-living/healthy-eating/salt-and-heart-health"},
{t:5,type:'s',stem:"For a man of European background, waist circumference shows substantially increased risk from",opts:["102 cm","80 cm","88 cm","94 cm"],ans:0,why:"Men: ≥ 94 increased, ≥ 102 substantially increased. Women: ≥ 80 and ≥ 88.",src:"https://www.ccm.health.qld.gov.au/management-of-diagnosed-conditions/overweight-and-obesity-adult"},
{t:5,type:'s',stem:"A client with obesity asks what weight loss would be worth it. A realistic first goal is",opts:["5-10% of current weight","reaching a BMI of 22","25% of current weight in 6 months","1-2 kg a week for a year"],ans:0,why:"5-10% weight loss improves blood pressure, glycaemia and lipids and is achievable.",src:"https://www.ccm.health.qld.gov.au/management-of-diagnosed-conditions/overweight-and-obesity-adult"},
{t:5,type:'s',stem:"The Heart Foundation recommends fish, preferably oily, about",opts:["2-3 times a week","once a month","twice a day","every day"],ans:0,why:"2-3 serves of fish a week provides about 250-500 mg EPA+DHA a day.",src:"https://www.heartfoundation.org.au/healthy-living/healthy-eating/fats-oils-and-heart-health"},
// 6 GI
{t:6,type:'c',case:'coeliac',stem:"What is the MOST important advice for Priya before the blood test?",opts:["Eat gluten daily again before testing","Stay gluten free to keep feeling better","Avoid only wheat but keep oats","Take iron for 2 weeks first"],ans:0,why:"A gluten-free diet before testing can give a false negative. Coeliac Australia advises a gluten challenge (≈ 4 slices of wheat bread a day for about 6 weeks).",src:"https://coeliac.org.au/learn/diagnosis/"},
{t:6,type:'c',case:'coeliac',stem:"If serology is positive, the diagnosis is usually confirmed by",opts:["small bowel biopsy","HLA-DQ2/DQ8 gene test","a skin prick test","a breath hydrogen test"],ans:0,why:"Biopsy (gastroscopy) confirms. Gene testing is useful to rule coeliac out, not in.",src:"https://coeliac.org.au/learn/diagnosis/"},
{t:6,type:'c',case:'coeliac',stem:"If coeliac disease is confirmed, which is TRUE for Priya in Australia?",opts:["Oats are not recommended","Small amounts of gluten are fine","Spelt bread is a safe swap","She can stop the diet when she feels better"],ans:0,why:"Coeliac Australia does not recommend oats. Spelt contains gluten. The diet is strict and lifelong.",src:"https://coeliac.org.au/live/gluten-free-diet/"},
{t:6,type:'s',stem:"The FIRST phase of the low FODMAP diet usually lasts",opts:["2-6 weeks","6-12 months","1-2 days","for life"],ans:0,why:"Short restriction (2-6 weeks), then reintroduction, then personalisation.",src:"https://www.monashfodmap.com/about-fodmap-and-ibs/"},
{t:6,type:'s',stem:"The first-line nutrition therapy to induce remission in a child with active Crohn's disease is",opts:["exclusive enteral nutrition","a low FODMAP diet","a gluten-free diet","a high-fibre diet"],ans:0,why:"EEN for 6-8 weeks is first line in paediatric Crohn's.",src:"https://crohnsandcolitis.org.au/living-with-crohns-colitis/lifestyle/nutrition/"},
{t:6,type:'s',stem:"A low-fibre diet in Crohn's disease is MOST appropriate when the patient",opts:["has an intestinal stricture","is in remission","has iron deficiency","wants to lose weight"],ans:0,why:"Low fibre reduces obstruction risk with strictures. It is not routine for everyone with IBD.",src:"https://crohnsandcolitis.org.au/living-with-crohns-colitis/lifestyle/nutrition/frequently-asked-dietary-questions-in-ibd/"},
{t:6,type:'e',emq:'diets',stem:"Confirmed coeliac disease",ans:0,why:"Strict lifelong gluten-free diet.",src:"https://coeliac.org.au/live/gluten-free-diet/"},
{t:6,type:'e',emq:'diets',stem:"IBS with bloating, coeliac disease excluded, first-line advice did not help",ans:1,why:"Low FODMAP is a second-line, time-limited trial with reintroduction.",src:"https://www.monashfodmap.com/about-fodmap-and-ibs/"},
// 7 Other clinical
{t:7,type:'c',case:'ckd',stem:"Which change will MOST help Mrs Nguyen's potassium level?",opts:["Limit high-potassium fruit to small amounts","Stop eating rice","Increase her protein intake","Add a salt substitute"],ans:0,why:"Her potassium is high and she eats a lot of fruit. Many salt substitutes are potassium chloride and are dangerous in CKD.",src:"https://kidney.org.au/your-kidneys/living-with-kidney-disease/health-and-wellbeing/diet-nutrition/"},
{t:7,type:'c',case:'ckd',stem:"For the consultation with Mrs Nguyen you should",opts:["book a professional interpreter","ask her son to translate","use written English handouts only","speak loudly and slowly"],ans:0,why:"Professional interpreters are best practice (TIS National). Family members may filter or misunderstand clinical information.",src:"https://www.health.gov.au/about-us/the-australian-health-system"},
{t:7,type:'s',stem:"Compared with CKD stage 4 not on dialysis, a person on haemodialysis usually needs",opts:["more protein","less protein","no protein change","protein only from plants"],ans:0,why:"Dialysis removes amino acids, so protein needs rise to about 1.0-1.2 g/kg/day.",src:"https://kidney.org.au/your-kidneys/living-with-kidney-disease/health-and-wellbeing/diet-nutrition/"},
{t:7,type:'s',stem:"A person with cirrhosis has muscle wasting. Which advice is MOST appropriate?",opts:["Add a late evening carbohydrate snack","Restrict protein to 0.5 g/kg","Fast overnight for 14 hours","Avoid all dietary fat"],ans:0,why:"A late evening snack shortens the overnight fast and reduces muscle breakdown. Protein should not be restricted.",src:"https://www.health.qld.gov.au/__data/assets/pdf_file/0031/145948/gastro-cldlong.pdf"},
{t:7,type:'s',stem:"IDDSI level 4 food is described as",opts:["pureed","minced and moist","soft and bite-sized","liquidised"],ans:0,why:"Level 4 = pureed (extremely thick for drinks). Level 3 liquidised, 5 minced and moist, 6 soft and bite-sized.",src:"https://www.iddsi.org/standards/framework"},
{t:7,type:'s',stem:"Who is responsible for assessing swallowing and recommending the IDDSI level?",opts:["Speech pathologist","Dietitian","Occupational therapist","Food service manager"],ans:0,why:"Speech pathology assesses swallowing. The dietitian ensures the modified diet meets nutrition and fluid needs.",src:"https://www.iddsi.org/standards/framework"},
{t:7,type:'s',stem:"A woman having chemotherapy has lost 4 kg and has a poor appetite. The FIRST approach is",opts:["small frequent high-energy high-protein meals","a weight-loss diet to reduce fat","a vegan diet to fight cancer","intravenous parenteral nutrition"],ans:0,why:"Food first: small frequent nourishing meals and snacks, then oral supplements if needed. PN only if the gut cannot be used.",src:"https://connect.cancer.org.au/cancer-information/living-and-coping/nutrition-for-people-with-cancer"},
{t:7,type:'e',emq:'diets',stem:"Cirrhosis with sarcopenia",ans:2,why:"Late evening carbohydrate snack and adequate protein.",src:"https://www.health.qld.gov.au/__data/assets/pdf_file/0031/145948/gastro-cldlong.pdf"},
{t:7,type:'e',emq:'diets',stem:"Post-stroke patient with dysphagia",ans:4,why:"Follow the speech pathologist's IDDSI prescription.",src:"https://www.iddsi.org/standards/framework"},
{t:7,type:'e',emq:'diets',stem:"Adult inpatient with an SGA rating of B and poor intake",ans:5,why:"Food-first fortification for mild/moderate malnutrition.",src:"https://www.health.qld.gov.au/__data/assets/pdf_file/0021/145830/nemo-hphe.pdf"},
{t:7,type:'e',emq:'diets',stem:"Paediatric Crohn's disease flare at diagnosis",ans:6,why:"EEN is first-line for remission in children.",src:"https://crohnsandcolitis.org.au/living-with-crohns-colitis/lifestyle/nutrition/"},
{t:7,type:'e',emq:'diets',stem:"Raised LDL cholesterol in a 50-year-old office worker",ans:7,why:"Heart-healthy pattern replacing saturated with unsaturated fat.",src:"https://www.heartfoundation.org.au/healthy-living/healthy-eating/heart-healthy-eating-pattern"},
// 8 Malnutrition & support
{t:8,type:'c',case:'refeed',stem:"Using the AuSPEN 2025 criteria, this man is",opts:["at risk of refeeding syndrome","not at risk, as his BMI is above 16","at risk only if he has diabetes","at risk only once feeding has started"],ans:0,why:"AuSPEN: at risk with two or more of: >10% weight loss in 3 months (or moderate-severe malnutrition), little or no intake for 7 days or more, problematic alcohol use, gastrointestinal losses. He has at least two.",src:"https://www.auspen.org.au/resources-3/2025/5/28/-auspen-consensus-statements-on-refeeding-syndrome"},
{t:8,type:'c',case:'refeed',stem:"Which should be given BEFORE feeding starts?",opts:["Thiamine","Vitamin K","Iron infusion","Vitamin A"],ans:0,why:"Thiamine before and during early feeding prevents Wernicke's encephalopathy, especially with alcohol misuse.",src:"https://www.auspen.org.au/resources-3/2025/5/28/-auspen-consensus-statements-on-refeeding-syndrome"},
{t:8,type:'c',case:'refeed',stem:"Under the AuSPEN 2025 consensus, his feeding should start at",opts:["at least 50% of his energy needs, reaching goal in 24-72 hours","5 kcal/kg/day for the first week","nothing until all electrolytes are normal","full goal rate with no blood tests"],ans:0,why:"AuSPEN no longer supports 'start low, go slow'. Start at 50% or more of estimated needs with thiamine, a multivitamin and close electrolyte monitoring, and reach goal within 24-72 hours. (Older NICE guidance started at 10 kcal/kg/day; you may still see it in older protocols.)",src:"https://www.auspen.org.au/resources-3/2025/5/28/-auspen-consensus-statements-on-refeeding-syndrome"},
{t:8,type:'c',case:'refeed',stem:"Which blood result is the hallmark of refeeding syndrome?",opts:["Low phosphate","High sodium","Low glucose","High albumin"],ans:0,why:"Hypophosphataemia is the classic sign as insulin drives phosphate into cells.",src:"https://www.auspen.org.au/resources-3/2025/5/28/-auspen-consensus-statements-on-refeeding-syndrome"},
{t:8,type:'s',stem:"A patient's MST score is 3 on admission. The NEXT step is",opts:["refer for full dietitian assessment","re-screen in 6 months","start parenteral nutrition","no action needed"],ans:0,why:"MST ≥ 2 means at risk; refer for full assessment (e.g. SGA).",src:"https://www.health.qld.gov.au/nutrition/patients/subjective-global-assessment-training-videos"},
{t:8,type:'s',stem:"Which is a food-first strategy for a patient with low intake?",opts:["Add milk powder to milk and porridge","Start a commercial supplement three times daily","Insert a nasogastric tube","Restrict fluids at meals"],ans:0,why:"Fortifying usual foods comes before supplements or tube feeding.",src:"https://www.health.qld.gov.au/__data/assets/pdf_file/0021/145830/nemo-hphe.pdf"},
{t:8,type:'s',stem:"A patient after major bowel surgery has a functioning gut but cannot eat enough for 7 days. The PREFERRED route is",opts:["enteral tube feeding","parenteral nutrition","intravenous dextrose only","nil by mouth until eating"],ans:0,why:"If the gut works, use it. Enteral is safer and cheaper than parenteral nutrition.",src:"https://www.nice.org.uk/guidance/cg32/chapter/Recommendations"},
// 9 Infants
{t:9,type:'c',case:'infant',stem:"What is the MOST important advice for Leo's parents?",opts:["Start iron-rich solids now, including peanut and egg","Delay peanut and egg until after 12 months","Keep exclusive breastfeeding until 12 months","Have him allergy tested before any solids"],ans:0,why:"ASCIA advises introducing common allergens in the first year; delay increases allergy risk. At 7 months he also needs iron-rich solids. Infants with severe eczema may need medical review first.",src:"https://allergy.org.au/hp/papers/infant-feeding-and-allergy-prevention/"},
{t:9,type:'c',case:'infant',stem:"Which growth chart should be used for Leo?",opts:["WHO growth chart","CDC growth chart","Brazilian national chart","Adult BMI chart"],ans:0,why:"WHO charts for 0-2 years in Australia.",src:"https://www.rch.org.au/childgrowth/about_child_growth/Growth_charts/"},
{t:9,type:'s',stem:"Solids should be introduced",opts:["around 6 months but not before 4 months","at 3 months to help sleep","after 12 months","only after teeth appear"],ans:0,why:"Around 6 months when developmentally ready, not before 4 months.",src:"https://www.rch.org.au/kidsinfo/fact_sheets/Nutrition_babies_toddlers/"},
{t:9,type:'s',stem:"Cow's milk can be given as the main drink from",opts:["12 months","6 months","3 months","2 years"],ans:0,why:"From 12 months. Before this, breast milk or infant formula.",src:"https://www.rch.org.au/kidsinfo/fact_sheets/Nutrition_babies_toddlers/"},
{t:9,type:'s',stem:"A 2-year-old drinks 1.2 L of cow's milk a day and eats little. The MAIN risk is",opts:["iron deficiency anaemia","vitamin C toxicity","calcium deficiency","hypoglycaemia"],ans:0,why:"Excess milk displaces iron-rich foods and is low in iron.",src:"https://www.rch.org.au/kidsinfo/fact_sheets/Nutrition_babies_toddlers/"},
{t:9,type:'s',stem:"Honey should not be given to infants under 12 months because of the risk of",opts:["botulism","tooth decay","allergy","diabetes"],ans:0,why:"Infant botulism from Clostridium botulinum spores.",src:"https://www.rch.org.au/kidsinfo/fact_sheets/Nutrition_babies_toddlers/"},
// 10 Pregnancy
{t:10,type:'c',case:'preg',stem:"Which supplements should Ana start?",opts:["Folic acid 400 µg and iodine 150 µg daily","Vitamin A and iron only","High-dose vitamin D only","No supplements are needed"],ans:0,why:"NHMRC: folic acid 400 µg (first 3 months, ideally from before conception) and iodine 150 µg daily in pregnancy.",src:"https://www.pregnancybirthbaby.org.au/vitamins-and-supplements-during-pregnancy"},
{t:10,type:'c',case:'preg',stem:"Which part of Ana's lunch is a listeria risk?",opts:["Brie cheese","Bread roll","Washed lettuce made fresh","Tomato"],ans:0,why:"Soft cheeses such as brie and camembert should be avoided unless cooked until steaming hot. Pre-prepared salads from cafés are also a risk.",src:"https://www.pregnancybirthbaby.org.au/pregnancy/nutrition-and-lifestyle/guide-to-food-and-drink-during-pregnancy"},
{t:10,type:'c',case:'preg',stem:"Recommended total weight gain for Ana is about",opts:["11.5-16 kg","5-9 kg","18-25 kg","2-4 kg"],ans:0,why:"Healthy pre-pregnancy BMI (18.5-24.9): about 11.5-16 kg.",src:"https://www.pregnancybirthbaby.org.au/pregnancy/nutrition-and-lifestyle/guide-to-food-and-drink-during-pregnancy"},
{t:10,type:'c',case:'preg',stem:"As a lacto-ovo vegetarian in pregnancy, which nutrient needs the MOST attention?",opts:["Iron","Vitamin C","Sodium","Carbohydrate"],ans:0,why:"Iron RDI rises to 27 mg in pregnancy and vegetarians need about 1.8 times more because non-haem iron is less absorbed.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients/iron"},
{t:10,type:'s',stem:"A pregnant woman loves fish. Which fish should she eat only once a fortnight, with no other fish that fortnight?",opts:["Shark (flake)","Salmon","Tinned tuna","Sardines"],ans:0,why:"FSANZ: shark/flake and billfish (swordfish, marlin) once a fortnight due to mercury.",src:"https://www.pregnancybirthbaby.org.au/pregnancy/nutrition-and-lifestyle/guide-to-food-and-drink-during-pregnancy"},
{t:10,type:'s',stem:"Since 2009, Australian bread-making flour must be fortified with",opts:["folic acid","vitamin D","iron","vitamin B12"],ans:0,why:"Mandatory folic acid fortification of wheat flour for bread, plus iodised salt in bread.",src:"https://www.pregnancybirthbaby.org.au/vitamins-and-supplements-during-pregnancy"},
// 11 Vegetarian & micronutrients
{t:11,type:'e',emq:'nutrients',stem:"A 3-year-old on a vegan diet with no fortified foods",ans:3,why:"B12 is found naturally only in animal foods; deficiency in young children harms development.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients/vitamin-b12"},
{t:11,type:'e',emq:'nutrients',stem:"A 15-year-old girl with heavy periods who skips meat",ans:1,why:"Menstrual losses plus low haem iron intake.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients/iron"},
{t:11,type:'e',emq:'nutrients',stem:"A woman planning pregnancy in the next 3 months",ans:4,why:"Folic acid before conception prevents neural tube defects.",src:"https://www.pregnancybirthbaby.org.au/vitamins-and-supplements-during-pregnancy"},
{t:11,type:'e',emq:'nutrients',stem:"A housebound 82-year-old who rarely goes outside",ans:5,why:"Vitamin D is made mostly from sun exposure.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients"},
{t:11,type:'e',emq:'nutrients',stem:"A 14-year-old with cow's milk allergy who drinks unfortified rice milk",ans:0,why:"Teens need 1300 mg calcium a day; unfortified rice milk provides very little.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients/calcium"},
{t:11,type:'e',emq:'nutrients',stem:"A man with alcohol dependence admitted with confusion and unsteady walking",ans:8,why:"Thiamine deficiency (Wernicke's encephalopathy).",src:"https://www.auspen.org.au/resources-3/2025/5/28/-auspen-consensus-statements-on-refeeding-syndrome"},
{t:11,type:'e',emq:'nutrients',stem:"A breastfeeding mother who uses non-iodised salt and eats no bread",ans:6,why:"Iodine needs rise in breastfeeding; bread with iodised salt is a main Australian source. NHMRC recommends 150 µg/day supplement.",src:"https://www.pregnancybirthbaby.org.au/vitamins-and-supplements-during-pregnancy"},
{t:11,type:'s',stem:"Which drink taken WITH a lentil curry will MOST improve iron absorption?",opts:["Orange juice","Black tea","Coffee","Milk"],ans:0,why:"Vitamin C enhances non-haem iron absorption. Tea, coffee and calcium reduce it.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients/iron"},
{t:11,type:'s',stem:"The RDI for calcium for a woman aged 55 is",opts:["1300 mg/day","1000 mg/day","800 mg/day","2500 mg/day"],ans:0,why:"Women 51+ need 1300 mg a day (2500 mg is the UL).",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients/calcium"},
{t:11,type:'s',stem:"Which is a reliable source of vitamin B12 for a vegan?",opts:["B12-fortified soy milk","Spirulina","Mushrooms","Seaweed"],ans:0,why:"Only fortified foods and supplements are reliable. Algae and mushrooms contain inactive analogues or tiny amounts.",src:"https://www.eatforhealth.gov.au/nutrient-reference-values/nutrients/vitamin-b12"},
// 12 Allergy
{t:12,type:'s',stem:"Which statement BEST describes lactose intolerance?",opts:["Non-immune; small amounts are often tolerated","Immune reaction that can cause anaphylaxis","Requires lifelong strict dairy avoidance","Diagnosed with a skin prick test"],ans:0,why:"Lactose intolerance is a lack of lactase, not an allergy. Many people tolerate small amounts, hard cheese and yoghurt.",src:"https://www.allergy.org.au/patients/food-allergy/ascia-dietary-avoidance-for-food-allergy"},
{t:12,type:'s',stem:"Which allergen must be declared on Australian food labels but is often missed by overseas-trained staff?",opts:["Lupin","Corn","Tomato","Rice"],ans:0,why:"Lupin is a mandatory allergen in Australia and New Zealand.",src:"https://www.foodstandards.gov.au/consumer/labelling/allergen-labelling"},
{t:12,type:'s',stem:"Under the Plain English Allergen Labelling (PEAL) rules, allergens must appear",opts:["in bold in the ingredient list and in a 'Contains' statement","only on the front of the pack","only as 'may contain'","only on the company website"],ans:0,why:"PEAL requires bold allergens in the ingredients list plus a separate summary statement, using set names.",src:"https://www.foodstandards.gov.au/consumer/labelling/allergen-labelling"},
{t:12,type:'s',stem:"A child under 4.5 years with cow's milk allergy should NOT be given",opts:["rice milk as their main milk","calcium-fortified soy milk","an extensively hydrolysed formula","breast milk"],ans:0,why:"Rice milk is low in protein and energy and contains arsenic; not suitable as main milk for young children.",src:"https://www.allergy.org.au/patients/food-allergy/ascia-dietary-avoidance-for-food-allergy"},
{t:12,type:'s',stem:"'May contain traces of nuts' on an Australian label is",opts:["voluntary precautionary labelling","a mandatory declaration","a legal guarantee of nut content","a Health Star Rating claim"],ans:0,why:"Precautionary allergen labelling is voluntary and not regulated by the Food Standards Code.",src:"https://www.foodstandards.gov.au/consumer/labelling/allergen-labelling"},
// 13 Aged care
{t:13,type:'c',case:'aged',stem:"What is the FIRST priority for Joan's diet?",opts:["Remove the 'diabetic diet' restriction","Start a weight-loss plan","Reduce her serve sizes","Add a low-fat diet"],ans:0,why:"Her diabetes is well controlled and she is malnourished. Liberalising restrictive diets helps intake.",src:"https://www.agedcarequality.gov.au/providers/food-nutrition-dining/food-nutrition-dining-resources-providers"},
{t:13,type:'c',case:'aged',stem:"Joan's MNA-SF score of 6 means she is",opts:["malnourished","at risk of malnutrition","normal nutritional status","not able to be screened"],ans:0,why:"MNA-SF: 0-7 malnourished, 8-11 at risk, 12-14 normal.",src:"https://www.agedcarequality.gov.au/quality-standards/guide-completing-mini-nutritional-assessment-short-form"},
{t:13,type:'c',case:'aged',stem:"Which referral is MOST relevant for Joan?",opts:["Dentist to review her dentures","Exercise physiologist for weight loss","Endocrinologist for insulin","Psychologist for anxiety"],ans:0,why:"Painful dentures are a direct, fixable cause of her low intake.",src:"https://www.agedcarequality.gov.au/providers/food-nutrition-dining/food-nutrition-dining-resources-providers"},
{t:13,type:'s',stem:"Healthy older adults generally need protein of about",opts:["1.0-1.2 g/kg/day","0.5 g/kg/day","2.5 g/kg/day","0.75 g/kg/day maximum"],ans:0,why:"Higher than younger adults to limit sarcopenia; more if ill or malnourished.",src:"https://www.agedcarequality.gov.au/providers/food-nutrition-dining/food-nutrition-dining-resources-providers"},
{t:13,type:'s',stem:"In the strengthened Aged Care Quality Standards, food and nutrition is covered by",opts:["Standard 6","Standard 1","Standard 3","Standard 8"],ans:0,why:"Standard 6: Food and nutrition.",src:"https://www.health.gov.au/resources/videos/new-aged-care-act-strengthened-aged-care-quality-standards-standard-6-the-food-and-nutrition"},
// 14 Food service
{t:14,type:'c',case:'menu',stem:"What is the BEST first change to the menu cycle?",opts:["Lengthen the cycle and add seasonal changes","Shorten it to one week","Remove all choice to cut costs","Offer only soup at every meal"],ans:0,why:"Long-stay residents need longer, varied, seasonal menus with choice.",src:"https://www.agedcarequality.gov.au/providers/food-nutrition-dining/food-nutrition-dining-resources-providers"},
{t:14,type:'c',case:'menu',stem:"The evening soup-and-sandwich meal is MOST likely to be a problem because it",opts:["is low in energy and protein for frail residents","is too high in fibre","is too expensive","is unsafe for all residents"],ans:0,why:"A light evening meal plus a long overnight fast increases malnutrition risk. Add a substantial meal or nourishing supper.",src:"https://www.health.vic.gov.au/sites/default/files/2022-08/nutrition-food-quality-standards-for-adults-vic-psracs-full-doc-pdf.PDF"},
{t:14,type:'c',case:'menu',stem:"To check texture-modified meals meet the IDDSI standard, staff should",opts:["use the IDDSI testing methods","rely on how the meal looks","ask residents if it is soft","weigh each meal"],ans:0,why:"IDDSI provides fork pressure, spoon tilt and flow tests.",src:"https://www.iddsi.org/standards/framework"},
{t:14,type:'s',stem:"A one-week menu cycle is MOST suitable for",opts:["an acute hospital with short stays","a residential aged care home","a long day care centre","a prison"],ans:0,why:"Short stays mean patients rarely see the cycle repeat. Long-stay settings need longer cycles.",src:"https://dietitiansaustralia.org.au/media/394"},
{t:14,type:'s',stem:"In a cook-chill system food is",opts:["cooked, rapidly chilled, stored, then reheated","cooked and served straight away","bought ready-made and only assembled","frozen for up to 6 months"],ans:0,why:"Cook-chill: cook, rapid chill, store (up to about 5 days), rethermalise.",src:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9796490/"},
{t:14,type:'s',stem:"A long day care menu that serves morning tea, lunch and afternoon tea should give 1-5 year olds about",opts:["50% of their daily nutrition needs","10% of their daily nutrition needs","100% of their daily nutrition needs","25% of their daily energy only"],ans:0,why:"HEAS menu planning guidelines (based on Get Up & Grow): morning tea, lunch and afternoon tea should provide about half of children's daily needs from the five food groups.",src:"https://heas.health.vic.gov.au/government-policies-and-guidelines/menu-planning-guidelines-for-long-day-care/"},
// 15 Food safety & labels
{t:15,type:'s',stem:"Cooked rice has been at room temperature for 3 hours. It should be",opts:["used now and not refrigerated","refrigerated for tomorrow","thrown out","reheated and refrigerated"],ans:0,why:"2-hour/4-hour rule: 2-4 hours between 5-60 °C means use it immediately, do not return to the fridge.",src:"https://www.foodstandards.gov.au/business/food-safety/2-hour-4-hour-rule"},
{t:15,type:'s',stem:"Cooked food must cool from 60 °C to 21 °C within",opts:["2 hours","4 hours","6 hours","30 minutes"],ans:0,why:"60→21 °C in 2 hours, then 21→5 °C in a further 4 hours.",src:"https://www.foodstandards.gov.au/business/food-safety/cooling-and-reheating-food"},
{t:15,type:'s',stem:"Hot food on a buffet should be held at",opts:["60 °C or above","40 °C or above","5 °C or below","37 °C"],ans:0,why:"Danger zone is 5-60 °C.",src:"https://www.foodstandards.gov.au/business/food-safety/2-hour-4-hour-rule"},
{t:15,type:'s',stem:"To compare the sugar content of two breakfast cereals, use the",opts:["per 100 g column","per serve column","front-of-pack claim","ingredient order only"],ans:0,why:"Serve sizes differ between brands; per 100 g allows a fair comparison.",src:"https://baker.edu.au/health-hub/fact-sheets/label-reading"},
{t:15,type:'s',stem:"In the HACCP system, a critical control point is",opts:["a step where control prevents or reduces a hazard","any step in food production","the final taste test","the delivery dock only"],ans:0,why:"A CCP is a step where control is essential to prevent, eliminate or reduce a food safety hazard to safe levels.",src:"https://www.foodauthority.nsw.gov.au/industry/audits-and-compliance/food-safety-programs-haccp"},
{t:15,type:'s',stem:"The Australia New Zealand Food Standards Code is developed by",opts:["FSANZ","the TGA","NHMRC","Dietitians Australia"],ans:0,why:"FSANZ develops standards; states and territories enforce them. The TGA regulates medicines and supplements.",src:"https://www.foodstandards.gov.au/food-standards-code"},
// 16 Public health
{t:16,type:'s',stem:"A rural town has high rates of obesity in teenage boys. Which intervention is MOST likely to work?",opts:["A co-designed after-school sport and cooking program","A leaflet sent home from school","A nutrition talk on local radio","A poster in the GP clinic"],ans:0,why:"Targeted, participatory, skills-based programs work better than passive information.",src:"https://www.aihw.gov.au/reports/australias-health/health-promotion"},
{t:16,type:'s',stem:"Counting how many families attended each session of a cooking program is",opts:["process evaluation","impact evaluation","outcome evaluation","needs assessment"],ans:0,why:"Process evaluation measures reach and delivery.",src:"https://www.health.nsw.gov.au/research/Pages/planning-evaluations-guide.aspx"},
{t:16,type:'s',stem:"Measuring change in vegetable intake 3 months after a program is",opts:["impact evaluation","process evaluation","outcome evaluation","formative evaluation"],ans:0,why:"Impact = short-term changes in knowledge, skills or behaviour. Outcome = long-term health change.",src:"https://www.health.nsw.gov.au/research/Pages/planning-evaluations-guide.aspx"},
{t:16,type:'s',stem:"Introducing healthy food policy in all public hospital cafés is an example of which Ottawa Charter action area?",opts:["Building healthy public policy","Developing personal skills","Strengthening community action","Reorienting health services"],ans:0,why:"Policy that changes what food is available is healthy public policy (also creates supportive environments).",src:"https://www.aihw.gov.au/reports/australias-health/health-promotion"},
{t:16,type:'s',stem:"Which group has the HIGHEST risk of food insecurity in Australia?",opts:["Aboriginal people in remote communities","Retired homeowners in cities","Dual-income couples","University staff"],ans:0,why:"Remote communities face high food prices, limited access and lower income.",src:"https://www.aihw.gov.au/reports/australias-health/social-determinants-of-health"},
// 17 Research
{t:17,type:'e',emq:'designs',stem:"Does a new oral supplement reduce falls in aged care residents compared with usual care?",ans:0,why:"An intervention effect is best tested by an RCT.",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
{t:17,type:'e',emq:'designs',stem:"What proportion of Australian adults currently meet vegetable recommendations?",ans:3,why:"Prevalence at one time point = cross-sectional survey.",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
{t:17,type:'e',emq:'designs',stem:"Was childhood diet associated with a rare liver cancer in adults?",ans:2,why:"Rare outcome: start with cases and look back at exposure.",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
{t:17,type:'e',emq:'designs',stem:"Do adults who eat more ultra-processed food develop more type 2 diabetes over 10 years?",ans:1,why:"Follow people forward by exposure: prospective cohort.",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
{t:17,type:'e',emq:'designs',stem:"How do Brazilian migrants experience Australian dietary advice?",ans:5,why:"Experiences and meanings: qualitative interviews.",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
{t:17,type:'s',stem:"A study reports a relative risk of 1.20 (95% CI 0.95-1.52). This result is",opts:["not statistically significant","significant and harmful","significant and protective","proof of causation"],ans:0,why:"The confidence interval includes 1.0, so no significant difference.",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
{t:17,type:'s',stem:"For a malnutrition SCREENING tool, the property that matters MOST is high",opts:["sensitivity","specificity","cost","length"],ans:0,why:"Screening should miss as few at-risk people as possible (few false negatives).",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
{t:17,type:'s',stem:"Coffee drinkers in a study had more heart disease, but they also smoked more. Smoking is a",opts:["confounder","outcome","sample","placebo"],ans:0,why:"Linked to both exposure and outcome, it distorts the association.",src:"https://www.cebm.ox.ac.uk/resources/ebm-tools/glossary"},
// 18 Practice
{t:18,type:'e',emq:'funding',stem:"A 60-year-old with type 2 diabetes sees her GP, who writes a plan and referral for 5 allied health visits",ans:0,why:"GPCCMP (from 1 July 2025) with referral: up to 5 allied health services a year.",src:"https://www.health.gov.au/about-us/the-australian-health-system"},
{t:18,type:'e',emq:'funding',stem:"A 25-year-old with an intellectual disability needs mealtime support funded in his plan",ans:1,why:"Disability-related supports are funded by the NDIS.",src:"https://www.health.gov.au/about-us/the-australian-health-system"},
{t:18,type:'e',emq:'funding',stem:"An 18-year-old with anorexia nervosa referred by her GP for up to 20 dietetic sessions",ans:3,why:"Eating Disorder Treatment Plans allow up to 20 dietetic services a year.",src:"https://www.health.gov.au/about-us/the-australian-health-system"},
{t:18,type:'e',emq:'funding',stem:"A former soldier with a Gold Card needs nutrition support for heart failure",ans:2,why:"DVA funds eligible veterans' allied health.",src:"https://www.health.gov.au/about-us/the-australian-health-system"},
{t:18,type:'s',stem:"Dietitians in Australia are",opts:["self-regulated through Dietitians Australia's APD program","registered with AHPRA like doctors","registered with each state government","not regulated at all"],ans:0,why:"Dietetics is not an AHPRA profession. The APD credential is the recognised standard.",src:"https://dietitiansaustralia.org.au/working-dietetics/standards-and-scope/code-conduct-dietitians-and-nutritionists"},
{t:18,type:'s',stem:"A client with limited English arrives with her 12-year-old daughter to translate. You should",opts:["arrange a professional interpreter","let the daughter translate","continue in English slowly","give her a translated leaflet and finish"],ans:0,why:"Use a professional interpreter (TIS National). Children should not interpret clinical information.",src:"https://www.health.gov.au/about-us/the-australian-health-system"},
{t:18,type:'s',stem:"Cultural safety is BEST judged by",opts:["the person receiving care","the dietitian","the hospital manager","a cultural awareness certificate"],ans:0,why:"Cultural safety is defined by the recipient of care, not the provider.",src:"https://dietitiansaustralia.org.au/working-dietetics/skills-recognition-australia/process-overseas-educated-dietitians/aboriginal-and-torres-strait-islander-cultural-awareness"},
{t:18,type:'s',stem:"A client asks you to keep his diagnosis secret from his wife, who rings you. You should",opts:["not share information without his consent","tell her because she is family","share only test results","tell her to ask the GP instead and give hints"],ans:0,why:"Confidentiality: share only with the client's consent (except legal or safety exceptions).",src:"https://dietitiansaustralia.org.au/working-dietetics/standards-and-scope/code-conduct-dietitians-and-nutritionists"},
// 19 Counselling & exam
{t:19,type:'s',stem:"'It sounds like you're worried that changing your diet will mean giving up the foods your family cooks.' This is an example of",opts:["a reflection","a closed question","giving advice","an affirmation"],ans:0,why:"Reflective listening restates the client's meaning and feeling (OARS).",src:"https://www.racgp.org.au/afp/2012/september/motivational-interviewing-techniques"},
{t:19,type:'s',stem:"A client says 'I know I should cut down on soft drink but I'm not ready yet.' Their stage of change is",opts:["contemplation","precontemplation","action","maintenance"],ans:0,why:"Aware of the problem and thinking about change but not ready to act.",src:"https://www.racgp.org.au/afp/2012/september/motivational-interviewing-techniques"},
{t:19,type:'s',stem:"Which is the BEST way to check a client's understanding at the end of education?",opts:["Ask them to explain the plan in their own words","Ask 'Do you understand?'","Give a written test","Repeat the information twice"],ans:0,why:"Teach-back checks understanding without making the client feel tested.",src:"https://www.seslhd.health.nsw.gov.au/teach-back"},
{t:19,type:'s',stem:"In the oral exam Task 3 phone call to a GP, the BEST structure is",opts:["ISBAR","SOAP notes read aloud","a PES statement only","small talk then the request"],ans:0,why:"ISBAR (Identify, Situation, Background, Assessment, Recommendation) is the standard Australian clinical handover format.",src:"https://dietitiansaustralia.org.au/media/1328"},
{t:19,type:'s',stem:"Which is an OPEN question?",opts:["What does a usual weekday look like for your meals?","Do you eat breakfast?","Is your appetite good?","Have you tried diets before?"],ans:0,why:"Open questions cannot be answered yes/no and invite the client to talk.",src:"https://www.racgp.org.au/afp/2012/september/motivational-interviewing-techniques"},
{t:19,type:'s',stem:"In oral exam Task 2 (education and counselling) you should assume",opts:["you will see the client again in a month","this is the only visit ever","the client has no goals","the GP will do the follow-up"],ans:0,why:"DA states candidates should plan as if they will see the client again in a month's time.",src:"https://dietitiansaustralia.org.au/working-dietetics/skills-recognition-australia/process-overseas-educated-dietitians/oral-exam"},
{t:19,type:'s',stem:"Which goal is written in the MOST SMART way?",opts:["Swap cola for sparkling water on 5 workdays each week for the next month","Drink less soft drink","Be healthier with drinks","Never drink soft drink again"],ans:0,why:"Specific, measurable, achievable, relevant and time-bound.",src:"https://www.health.nsw.gov.au/research/Pages/planning-evaluations-guide.aspx"}
];
